import { describe, expect, it } from "vitest";

import { GalleryArraySchema } from "@/core/Gallery.ts";
import { DeletedSubmissionSchema, SubmissionSchema } from "@/core/Submission.ts";

const baseSubmission =
  { id: 7, uploader: "Ana", isOwner: false, canModerate: false, creationTime: 1_700_000_000_000 };

describe("SubmissionSchema", () => {

  it("turns a base64 image into a PNG data URL", () => {
    const parsed = SubmissionSchema.parse({ ...baseSubmission, image: "iVBORw0KGgo=" });
    expect(parsed.image).toBe("data:image/png;base64,iVBORw0KGgo=");
  });

  it("turns non-base64 image text into an (escaped) SVG data URL", () => {
    const svg    = "<svg xmlns='http://www.w3.org/2000/svg'/>";
    const parsed = SubmissionSchema.parse({ ...baseSubmission, image: svg });
    expect(parsed.image).toBe(`data:image/svg+xml,${encodeURIComponent(svg)}`);
  });

  it("defaults missing comments to an empty array", () => {
    expect(SubmissionSchema.parse({ ...baseSubmission, image: "iVBORw0KGgo=" }).comments).toEqual([]);
    expect(SubmissionSchema.parse({ ...baseSubmission, image: "iVBORw0KGgo=", comments: null }).comments).toEqual([]);
  });

  it("coerces epoch-millisecond timestamps into Dates", () => {
    const parsed = SubmissionSchema.parse({ ...baseSubmission, image: "iVBORw0KGgo=" });
    expect(parsed.creationTime).toBeInstanceOf(Date);
    expect(parsed.creationTime.getTime()).toBe(1_700_000_000_000);
  });

  it("rejects a submission without an id", () => {
    const { id: _id, ...noID } = baseSubmission;
    expect(SubmissionSchema.safeParse({ ...noID, image: "iVBORw0KGgo=" }).success).toBe(false);
  });

});

describe("DeletedSubmissionSchema", () => {
  it("accepts the server's delete notification and rejects other shapes", () => {
    expect(DeletedSubmissionSchema.safeParse({ deletedID: 3 }).success).toBe(true);
    expect(DeletedSubmissionSchema.safeParse({ id: 3 }).success).toBe(false);
  });
});

describe("GalleryArraySchema", () => {

  const gallery =
    { id: "V1StGXR8_Z5jdHi6B-myT", name: "Period 1", template: "netlogo", isPrescreened: true
    , description: "", creationTime: 1_700_000_000_000, numApproved: 2, numWaiting: 1, lastSubTime: 1_700_000_100_000 };

  it("parses a well-formed listing", () => {
    expect(GalleryArraySchema.parse([gallery])).toHaveLength(1);
  });

  it("rejects ids that are not 21-character NanoIDs", () => {
    expect(GalleryArraySchema.safeParse([{ ...gallery, id: "too-short" }]).success).toBe(false);
  });

});
